[data-chat-composer-form] button[type="submit"]{border-radius:999px!important;background:var(--sx-accent-fill)!important;color:var(--sx-accent-fg)!important;border:none!important;box-shadow:0 0 0 1px color-mix(in srgb,var(--sx-accent) 40%,transparent),0 6px 18px -6px var(--sx-glow),inset 0 1px 0 rgb(255 255 255 / .22)!important;transition:scale var(--sx-sp-press-dur) var(--sx-sp-press),box-shadow var(--sx-med) var(--sx-ease),background-color var(--sx-med) var(--sx-ease),opacity var(--sx-med) var(--sx-ease)!important}
[data-chat-composer-form] button[type="submit"] svg{color:var(--sx-accent-fg)!important;stroke:var(--sx-accent-fg)!important}
[data-chat-composer-form] button[type="submit"]:hover:not(:disabled){scale:1.06;box-shadow:0 0 0 1px color-mix(in srgb,var(--sx-accent) 55%,transparent),0 8px 26px -6px var(--sx-glow),inset 0 1px 0 rgb(255 255 255 / .25)!important}
[data-chat-composer-form] button[type="submit"]:active:not(:disabled){scale:.9}
[data-chat-composer-form] button[type="submit"]:disabled{background:var(--sx-sunken)!important;box-shadow:inset 0 0 0 1px var(--sx-line)!important;opacity:1!important}
[data-chat-composer-form] button[type="submit"]:disabled svg{color:var(--sx-fg-4)!important;stroke:var(--sx-fg-4)!important}
/* --- the project picker in a new thread: an inline link in the heading, a chip under it --- */
[data-draft-project-trigger]{cursor:pointer;transition:color var(--sx-fast) var(--sx-ease),background-color var(--sx-fast) var(--sx-ease),text-decoration-color var(--sx-med) var(--sx-ease)}
h1 [data-draft-project-trigger]{color:var(--sx-accent-ink)!important;text-decoration:underline dotted 2px!important;text-decoration-color:color-mix(in srgb,var(--sx-accent) 45%,transparent)!important;text-underline-offset:.16em!important}
h1 [data-draft-project-trigger]:is(:hover,[data-popup-open]){text-decoration-style:solid!important;text-decoration-color:var(--sx-accent)!important}
p>[data-draft-project-trigger]{display:inline-flex!important;align-items:center!important;gap:6px;padding:3px 10px!important;border-radius:999px!important;font-size:13px!important;color:var(--sx-fg-2)!important;text-decoration:none!important;box-shadow:inset 0 0 0 1px var(--sx-line)}
p>[data-draft-project-trigger]:is(:hover,[data-popup-open]){background:var(--sx-hover)!important;color:var(--sx-fg)!important;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--sx-accent) 35%,transparent)}
p>[data-draft-project-trigger]::before,p>[data-draft-project-trigger]::after{content:"";background:currentColor}
p>[data-draft-project-trigger]::before{flex:0 0 13px;width:13px;height:13px;-webkit-mask:url("data:image/svg+xml,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20viewBox%3D'0%200%2024%2024'%20fill%3D'none'%20stroke%3D'black'%20stroke-width%3D'2'%20stroke-linejoin%3D'round'%3E%3Cpath%20d%3D'M20%2020a2%202%200%200%200%202-2V8a2%202%200%200%200-2-2h-7.9a2%202%200%200%201-1.69-.9L9.6%203.9A2%202%200%200%200%207.93%203H4a2%202%200%200%200-2%202v13a2%202%200%200%200%202%202Z'%2F%3E%3C%2Fsvg%3E") center/contain no-repeat;mask:url("data:image/svg+xml,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20viewBox%3D'0%200%2024%2024'%20fill%3D'none'%20stroke%3D'black'%20stroke-width%3D'2'%20stroke-linejoin%3D'round'%3E%3Cpath%20d%3D'M20%2020a2%202%200%200%200%202-2V8a2%202%200%200%200-2-2h-7.9a2%202%200%200%201-1.69-.9L9.6%203.9A2%202%200%200%200%207.93%203H4a2%202%200%200%200-2%202v13a2%202%200%200%200%202%202Z'%2F%3E%3C%2Fsvg%3E") center/contain no-repeat}
p>[data-draft-project-trigger]::after{flex:0 0 10px;width:10px;height:10px;opacity:.7;-webkit-mask:url("data:image/svg+xml,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20viewBox%3D'0%200%2024%2024'%20fill%3D'none'%20stroke%3D'black'%20stroke-width%3D'2.5'%20stroke-linecap%3D'round'%3E%3Cpath%20d%3D'm6%209%206%206%206-6'%2F%3E%3C%2Fsvg%3E") center/contain no-repeat;mask:url("data:image/svg+xml,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20viewBox%3D'0%200%2024%2024'%20fill%3D'none'%20stroke%3D'black'%20stroke-width%3D'2.5'%20stroke-linecap%3D'round'%3E%3Cpath%20d%3D'm6%209%206%206%206-6'%2F%3E%3C%2Fsvg%3E") center/contain no-repeat}
/* --- sidebar: a search pill, a lit New thread, quiet shelf labels, live timers --- */
